// Hierarchical Beta-Binomial model (rat tumor style)
//   y_i    ~ Binomial(n_i, theta_i)
//   theta_i ~ Beta(alpha, beta)
//   p(alpha, beta) proportional to (alpha + beta)^(-5/2)
data {
  int<lower=0> N;                       // number of groups
  array[N] int<lower=0> n;              // trials
  array[N] int<lower=0> y;              // successes
}
parameters {
  real<lower=0> alpha;
  real<lower=0> beta;
  vector<lower=0, upper=1>[N] theta;
}
model {
  // improper hyperprior: p(alpha, beta) ~ (alpha + beta)^(-5/2)
  target += -2.5 * log(alpha + beta);

  theta ~ beta(alpha, beta);
  y ~ binomial(n, theta);
}

