arguments.command:
mkdir -p /tmp/t && cat > /tmp/t/m2.stan <<'EOF'
data {
  int<lower=0> N;
  array[N] int<lower=0> n;
  array[N] int<lower=0> y;
}
parameters {
  real logit_phi;
  real log_kappa;
  vector<lower=0, upper=1>[N] theta;
}
transformed parameters {
  real<lower=0, upper=1> phi = inv_logit(logit_phi);
  real<lower=0> kappa = exp(log_kappa);
  real<lower=0> alpha = phi * kappa;
  real<lower=0> beta = (1 - phi) * kappa;
}
model {
  target += -2.5 * log(kappa);
  target += log(alpha) + log(beta) - log(kappa);   // Jacobian
  theta ~ beta(alpha, beta);
  y ~ binomial(n, theta);
}
EOF
cd /tmp/t && Rscript -e '
library(rstan); rstan_options(auto_write=TRUE); options(mc.cores=4)
d<-read.csv("/app/data.csv"); sd_<-list(N=nrow(d),n=as.integer(d$n),y=as.integer(d$y))
m<-stan_model("/tmp/t/m2.stan")
f<-sampling(m,data=sd_,chains=4,iter=20000,seed=1,refresh=0)
print(summary(f,pars=c("alpha","beta"))$summary)
' 2>&1 | tail -12

